insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, spoken_script_vi, spoken_script_en, tc, lc, tl, cvr_breakdown, source_metadata) values ('c3426d8c-84f3-5dc8-bf6a-ce861a5cf00d'::uuid, 'e0e61415-f370-53ed-a4ab-c4e3c8f57763'::uuid, 'f90629dd-2603-528a-8a1d-71c516d5f950'::uuid, 2, 'Package-Green-test.xlsx', 'Number 2', 'Ợ nóng', 'Heartburn', 'Hiện tượng ợ nóng kéo dài thường là tín hiệu cảnh báo về những rối loạn chức năng của cơ thể.', 'Prolonged heartburn is often a warning signal of dysfunctions of the body.', 'Hiện tượng ợ nóng kéo dài thường là tín hiệu cảnh báo về những rối loạn chức năng của cơ thể.', 'Prolonged heartburn is often a warning signal of dysfunctions of the body.', 13, 1, 1, '{"tc":13,"lc":1,"tl":1}'::jsonb, '{"sourceCciId":"green49q-cci-007","sourceCvrId":13,"sourceRow":46,"wordCountVi":21,"wordCountEn":12,"audioPlan":{"language":"en","teacherReadDirect":false}}'::jsonb);
insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, spoken_script_vi, spoken_script_en, tc, lc, tl, cvr_breakdown, source_metadata) values ('df0a28ce-cfbe-5f41-92dc-b73481fbbd17'::uuid, 'e0e61415-f370-53ed-a4ab-c4e3c8f57763'::uuid, 'f90629dd-2603-528a-8a1d-71c516d5f950'::uuid, 3, 'Package-Green-test.xlsx', 'Number 3', 'Đường huyết', 'Blood sugar', 'Việc tự đo lường chỉ số đường huyết giúp người bệnh kịp thời phát hiện những dấu hiệu bất thường khác.', 'Self-measuring blood sugar index helps patients detect other abnormal signs in time.', 'Việc tự đo lường chỉ số đường huyết giúp người bệnh kịp thời phát hiện những dấu hiệu bất thường khác.', 'Self-measuring blood sugar index helps patients detect other abnormal signs in time.', 13, 1, 1, '{"tc":13,"lc":1,"tl":1}'::jsonb, '{"sourceCciId":"green49q-cci-007","sourceCvrId":13,"sourceRow":47,"wordCountVi":21,"wordCountEn":12,"audioPlan":{"language":"en","teacherReadDirect":false}}'::jsonb);
insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, spoken_script_vi, spoken_script_en, tc, lc, tl, cvr_breakdown, source_metadata) values ('a30173c9-b89d-5630-89c2-16a92eb129e7'::uuid, 'e0e61415-f370-53ed-a4ab-c4e3c8f57763'::uuid, 'f90629dd-2603-528a-8a1d-71c516d5f950'::uuid, 4, 'Package-Green-test.xlsx', 'Number 4', 'Ngộ độc thực phẩm', 'Food poisoning', 'Sự bùng phát các vụ ngộ độc thực phẩm đặt ra yêu cầu cấp thiết về giám sát các cơ sở.', 'The outbreak of food poisoning incidents poses an urgent demand on supervising establishments.', 'Sự bùng phát các vụ ngộ độc thực phẩm đặt ra yêu cầu cấp thiết về giám sát các cơ sở.', 'The outbreak of food poisoning incidents poses an urgent demand on supervising establishments.', 13, 1, 1, '{"tc":13,"lc":1,"tl":1}'::jsonb, '{"sourceCciId":"green49q-cci-007","sourceCvrId":13,"sourceRow":48,"wordCountVi":21,"wordCountEn":13,"audioPlan":{"language":null,"teacherReadDirect":true}}'::jsonb);
insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, spoken_script_vi, spoken_script_en, tc, lc, tl, cvr_breakdown, source_metadata) values ('1635f0b6-b952-5989-9d91-98c93151277f'::uuid, 'e0e61415-f370-53ed-a4ab-c4e3c8f57763'::uuid, 'f90629dd-2603-528a-8a1d-71c516d5f950'::uuid, 5, 'Package-Green-test.xlsx', 'Number 5', 'Ngấn mỡ bụng', 'Love handles', 'Tập luyện đều đặn sẽ là giải pháp tối ưu giúp loại bỏ mấy cái ngấn mỡ bụng và cải thiện chỉ số quan trọng này.', 'Regular exercise will be the optimal solution to help remove love handles and improve this critical index.', 'Tập luyện đều đặn sẽ là giải pháp tối ưu giúp loại bỏ mấy cái ngấn mỡ bụng và cải thiện chỉ số quan trọng này.', 'Regular exercise will be the optimal solution to help remove love handles and improve this critical index.', 13, 1, 1, '{"tc":13,"lc":1,"tl":1}'::jsonb, '{"sourceCciId":"green49q-cci-007","sourceCvrId":13,"sourceRow":49,"wordCountVi":26,"wordCountEn":17,"audioPlan":{"language":null,"teacherReadDirect":true}}'::jsonb);
insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, spoken_script_vi, spoken_script_en, tc, lc, tl, cvr_breakdown, source_metadata) values ('b1574a51-3cba-53cb-bb56-cca88666bf05'::uuid, 'e0e61415-f370-53ed-a4ab-c4e3c8f57763'::uuid, 'f90629dd-2603-528a-8a1d-71c516d5f950'::uuid, 6, 'Package-Green-test.xlsx', 'Number 6', '"Có tâm"', 'Dedicated', 'Một người quản lý thực sự có tâm sẽ luôn nỗ lực tạo dựng một môi trường làm việc lành mạnh như thế này.', 'A truly dedicated manager will always strive to build a healthy working environment like this.', 'Một người quản lý thực sự có tâm sẽ luôn nỗ lực tạo dựng một môi trường làm việc lành mạnh như thế này.', 'A truly dedicated manager will always strive to build a healthy working environment like this.', 13, 1, 1, '{"tc":13,"lc":1,"tl":1}'::jsonb, '{"sourceCciId":"green49q-cci-007","sourceCvrId":13,"sourceRow":50,"wordCountVi":24,"wordCountEn":15,"audioPlan":{"language":null,"teacherReadDirect":true}}'::jsonb);
insert into public.test_items (id, package_version_id, section_id, item_order, source_day, source_stt, term_vi, term_en, prompt_vi, prompt_en, spoken_script_vi, spoken_script_en, tc, lc, tl, cvr_breakdown, source_metadata) values ('7d73b493-2f15-586c-a3bc-47efd9e49808'::uuid, 'e0e61415-f370-53ed-a4ab-c4e3c8f57763'::uuid, 'f90629dd-2603-528a-8a1d-71c516d5f950'::uuid, 7, 'Package-Green-test.xlsx', 'Number 7', 'Còn khuya mới...', 'Nowhere near... / far from...', 'Dự án nghiên cứu khoa học này còn khuya mới hoàn thành nếu thiếu sự hợp tác của những thành viên này.', 'This scientific research project is nowhere near completed if lacking cooperation of these members.', 'Dự án nghiên cứu khoa học này còn khuya mới hoàn thành nếu thiếu sự hợp tác của những thành viên này.', 'This scientific research project is nowhere near completed if lacking cooperation of these members.', 13, 1, 1, '{"tc":13,"lc":1,"tl":1}'::jsonb, '{"sourceCciId":"green49q-cci-007","sourceCvrId":13,"sourceRow":51,"wordCountVi":22,"wordCountEn":14,"audioPlan":{"language":null,"teacherReadDirect":true}}'::jsonb);
